import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { strict as assert } from 'node:assert';
import { withRuntime } from '../../../packages/workshop-tools/policy/runtime.ts';
import { sha256, repositoryRoot } from '../../../packages/workshop-tools/runtime-bundle.ts';
import { compareScores, scoreVector } from '../../../src/shared/policy/scoring.ts';
import type { Json, JsonObject, ScoreDefinition } from '../../../src/shared/policy/types';

type Row={seed:string;setupId:string;policy:string;metrics:JsonObject;digest:string;status:string};
const directory='test-results/cartographer-strength/score-assessment-2-final';
await mkdir(directory);
await withRuntime({game:'cartographer',retain:resolve(directory,'bundles')},async(runtime,provenance)=>{
 const definition=runtime.study.score;if(!definition)throw Error('No declared score2 definition');
 const paths=[
  ['historical-v2-reserved20','test-results/cartographer-policy/evaluation-1'],
  ['v3-development3','test-results/cartographer-strength/development-3'],
  ['v3-development4','test-results/cartographer-strength/development-4'],
 ];
 const timeFirst:ScoreDefinition={components:[definition.components[0],definition.components[1],definition.components[3],definition.components[2]]};
 const cohorts=[];
 for(const[label,path]of paths){
  const reportBytes=await readFile(resolve(path,'report.json'));
  const report=JSON.parse(reportBytes.toString())as{rows:Row[];seeds:string[];identity:unknown;provenance:{bundleDigest:string}};
  const nativePath=resolve(path,'bundles',report.provenance.bundleDigest+'.mjs');
  assert.equal(sha256(await readFile(nativePath)),report.provenance.bundleDigest);
  const frozenNative=await import(pathToFileURL(nativePath).href);
  const cases=[];
  for(const row of report.rows){
   const name=`${row.seed}-${row.setupId}-${row.policy}`;
   const rawBytes=await readFile(resolve(path,name+'.rollout.json'));
   const run=runtime.parseRollout(rawBytes.toString());
   assert.equal(run.digest,row.digest);
   const native=frozenNative.adapter.restore(run.replay);
   const metrics=runtime.adapter.metrics(native);
   for(const[key,value]of Object.entries(row.metrics))assert.deepEqual(metrics[key],value,`${name}:${key}`);
   const nativeCommands=(run.replay as {commands:Json[]}).commands.length;
   assert.equal(nativeCommands,runtime.adapter.cursor(native));assert.equal(nativeCommands,run.episode.cursor);
   const score=scoreVector(definition,metrics.score);
   assert.equal(score[3],row.metrics.won===1?nativeCommands:0);
   cases.push({case:name,seed:row.seed,tier:row.setupId,policy:row.policy,status:row.status,sourceRolloutDigest:run.digest,sourceBytesDigest:sha256(rawBytes),nativeAcceptedCommands:nativeCommands,score});
  }
  const at=(seed:string,tier:string,policy:string)=>cases.find(c=>c.seed===seed&&c.tier===tier&&c.policy===policy)!;
  const comparisons=(as:typeof cases,bs:typeof cases)=>{
   const signs=as.map((a,i)=>compareScores(definition,a.score,bs[i].score));
   const speedSigns=as.map((a,i)=>compareScores(timeFirst,[a.score[0],a.score[1],a.score[3],a.score[2]],[bs[i].score[0],bs[i].score[1],bs[i].score[3],bs[i].score[2]]));
   const counts=(values:number[])=>({aBetter:values.filter(v=>v>0).length,bBetter:values.filter(v=>v<0).length,tied:values.filter(v=>v===0).length,n:values.length});
   return{healthFirst:counts(signs),commandFirstSensitivity:counts(speedSigns)};
  };
  const mean=(values:number[])=>values.length?values.reduce((a,b)=>a+b,0)/values.length:null;
  const summary=['relaxed','standard','severe'].flatMap(tier=>['immediate','survival','growth'].map(policy=>{
   const group=cases.filter(c=>c.tier===tier&&c.policy===policy),wins=group.filter(c=>c.score[0]===1);
   return{tier,policy,attempts:group.length,wins:wins.length,victoriousHealthFractionMean:mean(wins.map(c=>c.score[2])),victoriousAcceptedCommandsMean:mean(wins.map(c=>c.score[3])),timeouts:group.filter(c=>c.status==='timeout').length};
  }));
  const policyPairs=['relaxed','standard','severe'].flatMap(tier=>[['survival','immediate'],['survival','growth'],['growth','immediate']].map(([a,b])=>({tier,a,b,...comparisons(report.seeds.map(s=>at(s,tier,a)),report.seeds.map(s=>at(s,tier,b)))})));
  const tierPairs=['immediate','survival','growth'].flatMap(policy=>[['relaxed','standard'],['standard','severe']].map(([a,b])=>({policy,a,b,...comparisons(report.seeds.map(s=>at(s,a,policy)),report.seeds.map(s=>at(s,b,policy)))})));
  cohorts.push({label,sourceReport:path+'/report.json',frozenNativeBundleDigest:report.provenance.bundleDigest,sourceReportDigest:sha256(reportBytes),originalIdentity:report.identity,independentBlocks:report.seeds.length,summary,policyPairs,tierPairs,cases});
 }
 const analysisDigests=Object.fromEntries(await Promise.all(['src/shared/policy/scoring.ts','.work/sessions/cartographer-strength-2026-10-16/rescore-2.ts'].map(async path=>[path,sha256(await readFile(path))])));
 for(const[path,hash]of Object.entries({...provenance.sourceDigests,...provenance.toolDigests,...analysisDigests}))assert.equal(sha256(await readFile(resolve(repositoryRoot,path))),hash,`Source drift:${path}`);
 const analysisSource=await readFile('.work/sessions/cartographer-strength-2026-10-16/rescore-2.ts','utf8');
 const receipt={analysisSource,schema:'cartographer-posthoc-performance-2',identity:runtime.adapter.identity,definition,ranking:runtime.study.ranking,provenance,analysisDigests,postHoc:true,freshPolicyExecution:false,nativeReconstruction:true,sourceMetricsUnchanged:true,confirmation:false,limits:'Existing development and historical reserved cases are reused post hoc. No new reserved inference or win-rate confirmation. Health-first versus command-first sensitivity is an objective preference, not a universal strength ordering.',cohorts};
 await writeFile(resolve(directory,'receipt.json'),JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});
 console.log(JSON.stringify({identity:receipt.identity,cohorts:cohorts.map(({label,summary,policyPairs,tierPairs,cases})=>({label,cases:cases.length,summary,policyPairs,tierPairs}))},null,2));
});

