import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { strict as assert } from 'node:assert';
const sha=(bytes: string|Buffer)=>createHash('sha256').update(bytes).digest('hex');
const path='test-results/cartographer-strength/score-assessment-2-final/receipt.json';
const receiptBytes=await readFile(path);const receipt=JSON.parse(receiptBytes.toString());
let count=0;
for(const cohort of receipt.cohorts)for(const row of cohort.cases){
 const bytes=await readFile(resolve(dirname(cohort.sourceReport),row.case+'.rollout.json'));
 assert.equal(sha(bytes),row.sourceBytesDigest);
 const {digest,...payload}=JSON.parse(bytes.toString());
 assert.equal(sha(JSON.stringify(payload)),digest);
 assert.equal(digest,row.sourceRolloutDigest);count++;
}
assert.equal(count,900);
const source=await readFile('.work/sessions/cartographer-strength-2026-10-16/verify-score-digests.ts','utf8');
const audit={cases:count,canonicalDigestMatches:count,originalBytesMatch:count,sidecarReceiptDigest:sha(receiptBytes),source,sourceDigest:sha(source),freshInputReconstruction:false,freshPolicyExecution:false};
await writeFile('test-results/cartographer-strength/score-assessment-2-final/digest-audit.json',JSON.stringify(audit,null,2)+'\n',{flag:'wx'});
await writeFile('docs/research/experiments/2026-10-16-cartographer-performance-2.json',JSON.stringify({...receipt,canonicalDigestAudit:audit},null,2)+'\n');
console.log(JSON.stringify({cases:count,canonicalDigestMatches:count,originalBytesMatch:count}));
